interface Loan {
  id: number;
  approved: boolean;
  rejected: boolean;
  approvedBy?: string;
}

function describe(loan: Loan): string {
  if (loan.rejected) return `#${loan.id} rejected`;
  if (loan.approved) return `#${loan.id} approved by ${loan.approvedBy}`;
  return `#${loan.id} pending`;
}

console.log(describe({ id: 1, approved: true, rejected: true, approvedBy: "Ngozi" }));
console.log(describe({ id: 2, approved: true, rejected: false }));

function toKobo(amount: number | string): number {
  if (typeof amount === "number") return Math.round(amount * 100);
  return Math.round(Number(amount.replace(/,/g, "")) * 100);
}

console.log(toKobo(25.5), toKobo("1,200.75"));

type Loan =
  | { status: "pending"; amount: number }
  | { status: "approved"; amount: number }
  | { status: "disbursed"; amount: number };

function fee(loan: Loan): number {
  switch (loan.status) {
    case "pending":
      return 0;
    case "approved":
    case "disbursed":
      return Math.round(loan.amount * 0.015);
  }
}

console.log(fee({ status: "pending", amount: 40000 }), fee({ status: "disbursed", amount: 40000 }));

type Status = "pending" | "approved";

function assertNever(value: never): never {
  throw new Error(`Unhandled: ${JSON.stringify(value)}`);
}

function label(status: Status): string {
  switch (status) {
    case "pending":
      return "Waiting";
    case "approved":
      return "Approved";
    default:
      return assertNever(status);
  }
}

const fromDb = JSON.parse('["approved", "on-hold"]');
for (const s of fromDb) {
  try {
    console.log(label(s));
  } catch (error) {
    console.log((error as Error).message);
  }
}

type AccountStatus = "active" | "dormant" | "closed" | "frozen";

function canWithdraw(status: AccountStatus): boolean {
  if (status === "closed") return false;
  else if (status === "dormant") return false;
  else return true;
}

console.log(canWithdraw("active"), canWithdraw("frozen"));

type WithdrawResult =
  | { ok: true; balance: number }
  | { ok: false; error: "insufficient-funds" | "below-minimum" };

function withdraw(balance: number, amount: number): WithdrawResult {
  if (amount < 500) return { ok: false, error: "below-minimum" };
  if (amount > balance) return { ok: false, error: "insufficient-funds" };
  return { ok: true, balance: balance - amount };
}

for (const amount of [200, 3000, 9000]) {
  const r = withdraw(5000, amount);
  console.log(r.ok ? r.balance : r.error);
}

