type TransferResult = { ok: true; newBalance: number } | { ok: false; error: "frozen" | "insufficient-funds" };

function transfer(balance: number, amount: number, frozen: boolean): TransferResult {
  if (frozen) return { ok: false, error: "frozen" };
  if (amount > balance) return { ok: false, error: "insufficient-funds" };
  return { ok: true, newBalance: balance - amount };
}

for (const [amount, frozen] of [[2500, false], [20000, false], [100, true]] as const) {
  const r = transfer(10000, amount, frozen);
  console.log(r.ok ? `ok ${r.newBalance}` : `failed: ${r.error}`);
}

