type Loan = { status: "pending"; amount: number } | { status: "approved"; amount: number; approvedBy: string };
type Audited = Loan & { createdBy: string; createdAt: string };

function trail(loan: Audited): string {
  const approval = loan.status === "approved" ? `, approved by ${loan.approvedBy}` : "";
  return `created ${loan.createdAt} by ${loan.createdBy}${approval}`;
}

console.log(trail({ status: "pending", amount: 9000, createdBy: "app", createdAt: "2026-09-20" }));
console.log(trail({ status: "approved", amount: 9000, approvedBy: "Ngozi", createdBy: "teller-7", createdAt: "2026-09-21" }));

