type Booking =
  | { status: "held"; id: number; expiresAt: string }
  | { status: "confirmed"; id: number; paymentRef: string };

function summary(b: Booking): string {
  switch (b.status) {
    case "held":
      return `#${b.id} held until ${b.expiresAt}`;
    case "confirmed":
      return `#${b.id} confirmed (${b.paymentRef})`;
  }
}

console.log(summary({ status: "held", id: 1, expiresAt: "18:00" }));
console.log(summary({ status: "confirmed", id: 2, paymentRef: "PAY-771" }));

